// === Tab: truchet ===
let sTile = 41;
let c0 = color(0),
      c1;

function setup()
{
  createCanvas(820, 615);
  noStroke();
  newColor();
}


function draw()
{
  for (let x = 0; x < width; x += (Math.max(0.001, Math.abs(sTile)) || 1))
  {
    for (let y = 0; y < height; y += (Math.max(0.001, Math.abs(sTile)) || 1))
    {
      if (int(random(2)) == 0) fill(c0);
      else fill(c1);
      rect(x, y, sTile, sTile);
    }
  }

  for (let x = 0; x < width + 1; x += (Math.max(0.001, Math.abs(sTile)) || 1))
  {
    for (let y = 0; y < height + 1; y += (Math.max(0.001, Math.abs(sTile)) || 1))
    {
      if ((x+y)%2 ==0) fill(c0);
      else fill(c1);
      ellipse(x, y, sTile, sTile);
    }
  }

  // noLoop() removed for animation
}


function mouseReleased()  //new pattern
{
  loop();
}


function keyPressed()
{
  if (key == ' ')  //new pattern with new color
  {
    newColor();
    loop();
  }
}


